package ds.seed9006;

import ds.Identifier;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.Test;
import org.junit.experimental.categories.Category;
import org.junit.runner.RunWith;

import static org.junit.Assert.*;

/**
 * Requirement traceability: REQ-IDENT-001 - Identifier validation rules (letters/digits allowed, other punctuation disallowed).
 *
 * These tests improve on autogenerated ones by:
 * - Adding consistency/idempotence checks (multiple invocations yield same result).
 * - Exercising a few boundary-like scenarios (null, single-char, whitespace/trailing space).
 * - Providing descriptive assertion messages for easier diagnosis.
 *
 * Note: This class intentionally retains the original test method names (test0..test5) required by the evaluation harness.
 */
interface UnitTest {
}

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, useJEE = true)
@Category(UnitTest.class)
public class EvoAITest extends Identifier_ESTest_scaffolding {

    /**
     * Given an identifier string containing punctuation and braces,
     * when validateIdentifier is invoked,
     * then the identifier should be rejected (consistent and idempotent).
     */
    @Test(timeout = 4000)
    public void test0() throws Throwable {
        // Given
        Identifier identifier0 = new Identifier();
        String input = "'S}7Fudbf";

        // When
        boolean first = identifier0.validateIdentifier(input);

        // Then
        assertFalse("Expected identifier with punctuation and brace to be invalid: " + input, first);

        // And: idempotence (multiple calls produce same result)
        boolean second = identifier0.validateIdentifier(input);
        assertEquals("validateIdentifier should be idempotent for input: " + input, first, second);

        // Additional sanity check: verify reported length is as expected (defensive check not tied to validation rules)
        assertEquals("Input length should match expected", 9, input.length());
    }

    /**
     * Given a single punctuation character,
     * when checking valid_s,
     * then it should return false; also verify a known letter returns true and behavior is consistent.
     */
    @Test(timeout = 4000)
    public void test1() throws Throwable {
        // Given
        Identifier identifier0 = new Identifier();
        char invalidChar = '}';
        char knownLetter = 'w';

        // When & Then: invalid punctuation
        boolean invalidResult = identifier0.valid_s(invalidChar);
        assertFalse("Expected '}' to be considered invalid by valid_s", invalidResult);

        // When & Then: known letter should be considered valid (observed behavior)
        boolean letterResult = identifier0.valid_s(knownLetter);
        assertTrue("Expected lowercase letter 'w' to be considered valid by valid_s", letterResult);

        // Idempotence checks
        assertEquals("valid_s should be idempotent for '}'", invalidResult, identifier0.valid_s(invalidChar));
        assertEquals("valid_s should be idempotent for 'w'", letterResult, identifier0.valid_s(knownLetter));
    }

    /**
     * Given a single-letter identifier,
     * when validateIdentifier is invoked,
     * then it should be accepted; also ensure repeated calls yield same outcome.
     */
    @Test(timeout = 4000)
    public void test2() throws Throwable {
        // Given
        Identifier identifier0 = new Identifier();
        String singleLetter = "w";

        // When
        boolean result = identifier0.validateIdentifier(singleLetter);

        // Then
        assertTrue("Expected single-letter identifier to be valid: " + singleLetter, result);

        // And: idempotence
        boolean repeated = identifier0.validateIdentifier(singleLetter);
        assertEquals("Repeated validation should yield same result for: " + singleLetter, result, repeated);

        // Boundary-like check: ensure string length is 1
        assertEquals("Sanity: input for this test should be length 1", 1, singleLetter.length());
    }

    /**
     * Given an identifier with trailing space,
     * when validateIdentifier is invoked,
     * then it should be rejected; verify idempotence and that the input contains whitespace.
     */
    @Test(timeout = 4000)
    public void test3() throws Throwable {
        // Given
        Identifier identifier0 = new Identifier();
        String input = "EpDQk7 ";

        // Precondition: input contains at least one whitespace character (ensures test covers whitespace case)
        boolean hasWhitespace = false;
        for (int i = 0; i < input.length(); i++) {
            if (Character.isWhitespace(input.charAt(i))) {
                hasWhitespace = true;
                break;
            }
        }
        assertTrue("Test setup expects input to contain whitespace: '" + input + "'", hasWhitespace);

        // When
        boolean result = identifier0.validateIdentifier(input);

        // Then
        assertFalse("Expected identifier with trailing whitespace to be invalid: '" + input + "'", result);

        // Idempotence
        assertEquals("validateIdentifier should be idempotent for input with trailing space", result, identifier0.validateIdentifier(input));
    }

    /**
     * Given an identifier with special characters and space,
     * when validateIdentifier is invoked,
     * then it should be rejected; check idempotence and basic sanity properties.
     */
    @Test(timeout = 4000)
    public void test4() throws Throwable {
        // Given
        Identifier identifier0 = new Identifier();
        String input = ":&Aok7bNm<xUo0L M";

        // Sanity: ensure the input is not null and has expected minimal length
        assertNotNull("Test input must not be null", input);
        assertTrue("Test input should be reasonably long to act as a boundary-like case", input.length() > 5);

        // When
        boolean result = identifier0.validateIdentifier(input);

        // Then
        assertFalse("Expected identifier with special characters and internal space to be invalid: '" + input + "'", result);

        // Idempotence
        assertEquals("validateIdentifier should return same result on subsequent calls for: '" + input + "'", result, identifier0.validateIdentifier(input));
    }

    /**
     * Given a null identifier,
     * when validateIdentifier is invoked,
     * then it should safely return false (no exception), and be idempotent.
     */
    @Test(timeout = 4000)
    public void test5() throws Throwable {
        // Given
        Identifier identifier0 = new Identifier();

        // When
        boolean result = identifier0.validateIdentifier((String) null);

        // Then
        assertFalse("Expected null input to be treated as invalid (safe false)", result);

        // Idempotence: calling again should not throw and should return same result
        boolean repeated = identifier0.validateIdentifier((String) null);
        assertEquals("Repeated null validation should yield same result", result, repeated);
    }
}